/** Asset system model */
type GCMS_Asset = GCMS_Entity & GCMS_Node & {
  /** The time the document was created */
  readonly createdAt: Scalars['GCMS_DateTime'];
  /** User that created this document */
  readonly createdBy: Maybe<GCMS_User>;
  /** Get the document in other stages */
  readonly documentInStages: ReadonlyArray<GCMS_Asset>;
  /** The file name */
  readonly fileName: Scalars['String'];
  /** The file handle */
  readonly handle: Scalars['String'];
  /** The height of the file */
  readonly height: Maybe<Scalars['Float']>;
  /** List of Asset versions */
  readonly history: ReadonlyArray<GCMS_Version>;
  /** The unique identifier */
  readonly id: Scalars['ID'];
  /** System Locale field */
  readonly locale: GCMS_Locale;
  /** Get the other localizations for this document */
  readonly localizations: ReadonlyArray<GCMS_Asset>;
  /** The mime type of the file */
  readonly mimeType: Maybe<Scalars['String']>;
  readonly moviePreview: ReadonlyArray<GCMS_Movie>;
  readonly previewBlog: ReadonlyArray<GCMS_Blog>;
  readonly previewImageWork: ReadonlyArray<GCMS_Work>;
  /** The time the document was published. Null on documents in draft stage. */
  readonly publishedAt: Maybe<Scalars['GCMS_DateTime']>;
  /** User that last published this document */
  readonly publishedBy: Maybe<GCMS_User>;
  readonly scheduledIn: ReadonlyArray<GCMS_ScheduledOperation>;
  /** The file size */
  readonly size: Maybe<Scalars['Float']>;
  /** System stage field */
  readonly stage: GCMS_Stage;
  /** The time the document was updated */
  readonly updatedAt: Scalars['GCMS_DateTime'];
  /** User that last updated this document */
  readonly updatedBy: Maybe<GCMS_User>;
  /** Returns information you need to upload the asset. The type of upload is dependant on what you pass into asset creations as upload type. */
  readonly upload: Maybe<GCMS_AssetUpload>;
  /** Get the url for the asset with provided transformations applied. */
  readonly url: Scalars['String'];
  /** The file width */
  readonly width: Maybe<Scalars['Float']>;
};


