type GCMS_ImageBlurInput = {
  /** The amount of blurring to apply to the image. The value must be an integer from 1 to 20. */
  readonly amount: Scalars['Int'];
};

/** Adds a border to the image. */
type GCMS_ImageBorderInput = {
  /** The background color of the border. The value must be a valid hex color code. Or one of the supported color names. */
  readonly background: Scalars['String'];
  /** The color of the border. The value must be a valid hex color code. Or one of the supported color names. */
  readonly color: Scalars['String'];
  /** The width of the border in pixels. The value must be an integer from 1 to 1000. */
  readonly width: Scalars['Int'];
};

type GCMS_ImageCompressInput = {
  /** Preserves the metadata of the image. */
  readonly metadata: Scalars['Boolean'];
};

/**
 * Crops the image to the specified dimensions.
 * The starting points for X and Y coordinates are [0,0], aligning with the top-left corner of the image.
 * The width and height parameters determine the size in pixels of the cropping rectangle.
 * The output will include only the portion of the image within the designated crop area.
 */
type GCMS_ImageCropInput = {
  /** The height in pixels to resize the image to. The value must be an integer from 1 to 10000. */
  readonly height: Scalars['Int'];
  /** The width in pixels to resize the image to. The value must be an integer from 1 to 10000. */
  readonly width: Scalars['Int'];
  /** The x coordinate of the image. The value must be an integer from 0 to 10000. */
  readonly x: Scalars['Int'];
  /** The y coordinate of the image. The value must be an integer from 0 to 10000. */
  readonly y: Scalars['Int'];
};

type GCMS_ImageFit =
  /** Resizes the image to fit within the specified parameters without distorting, cropping, or changing the aspect ratio. */
  | 'clip'
  /** Resizes the image to fit the specified parameters exactly by removing any parts of the image that don't fit within the boundaries. */
  | 'crop'
  /** Resizes the image to fit within the parameters, but as opposed to 'fit:clip' will not scale the image if the image is smaller than the output size. */
  | 'max'
  /** Resizes the image to fit the specified parameters exactly by scaling the image to the desired size. The aspect ratio of the image is not respected and the image can be distorted using this method. */
  | 'scale';

type GCMS_ImageQualityInput = {
  /** The quality of the image. The value must be an integer from 1 to 100. */
  readonly value: Scalars['Int'];
};

type GCMS_ImageResizeInput = {
  /** The default value for the fit parameter is fit:clip. */
  readonly fit: InputMaybe<GCMS_ImageFit>;
  /** The height in pixels to resize the image to. The value must be an integer from 1 to 10000. */
  readonly height: InputMaybe<Scalars['Int']>;
  /** The width in pixels to resize the image to. The value must be an integer from 1 to 10000. */
  readonly width: InputMaybe<Scalars['Int']>;
};

type GCMS_ImageSharpenInput = {
  /** The amount of sharpening to apply to the image. The value must be an integer from 1 to 20. */
  readonly amount: Scalars['Int'];
};

/** Transformations for Images */
type GCMS_ImageTransformationInput = {
  /** Blurs the image. */
  readonly blur: InputMaybe<GCMS_ImageBlurInput>;
  /** Adds a border to the image. */
  readonly border: InputMaybe<GCMS_ImageBorderInput>;
  /** Compresses the image. */
  readonly compress: InputMaybe<GCMS_ImageCompressInput>;
  /** Crops the image to the specified dimensions. */
  readonly crop: InputMaybe<GCMS_ImageCropInput>;
  /**
   * Changes the quality of the image. The value must be an integer from 1 to 100.
   * Only supported for the following formats jpeg, jpg, webp, gif, heif, tiff, avif.
   */
  readonly quality: InputMaybe<GCMS_ImageQualityInput>;
  /** Resizes the image */
  readonly resize: InputMaybe<GCMS_ImageResizeInput>;
  /** Sharpens the image. */
  readonly sharpen: InputMaybe<GCMS_ImageSharpenInput>;
};

